package unified

import (
	"encoding/json"
	"math"
	"testing"
)

func TestPHPJSONByteCompatibility(t *testing.T) {
	// Expected bytes were generated by PHP 8.3 json_encode, not Go Marshal.
	value := Array{"a/b", "中文😀", "<>&'\"", "\n\x1b\u2028\u2029", true, nil,
		json.Number("9223372036854775807"), json.Number("9007199254740993"),
		json.Number("30.0"), 1e-7, 1e16, 1e17, math.Copysign(0, -1)}
	cases := []struct {
		name             string
		unescapedSlashes bool
		want             string
	}{
		{"default", false, `["a\/b","\u4e2d\u6587\ud83d\ude00","<>&'\"","\n\u001b\u2028\u2029",true,null,9223372036854775807,9007199254740993,30,1.0e-7,10000000000000000,1.0e+17,-0]`},
		{"unescaped-slashes", true, `["a/b","\u4e2d\u6587\ud83d\ude00","<>&'\"","\n\u001b\u2028\u2029",true,null,9223372036854775807,9007199254740993,30,1.0e-7,10000000000000000,1.0e+17,-0]`},
	}
	for _, test := range cases {
		t.Run(test.name, func(t *testing.T) {
			got, err := PHPJSON(value, test.unescapedSlashes)
			if err != nil {
				t.Fatal(err)
			}
			if string(got) != test.want {
				t.Fatalf("PHP identity bytes differ\ngot  %s\nwant %s", got, test.want)
			}
		})
	}
}

func TestPHPJSONOrderedTicketObject(t *testing.T) {
	value := PHPObject{{"v", 1}, {"u", "https://media.example/a/b?name=%E4%B8%AD"}, {"iat", int64(1800000000)}, {"exp", int64(1800001800)}}
	got, err := PHPJSON(value, true)
	if err != nil {
		t.Fatal(err)
	}
	const want = `{"v":1,"u":"https://media.example/a/b?name=%E4%B8%AD","iat":1800000000,"exp":1800001800}`
	if string(got) != want {
		t.Fatalf("ordered signed bytes differ: %s", got)
	}
}

func TestPHPJSONRejectsUnorderedAndInvalidIdentityValues(t *testing.T) {
	for _, input := range []any{Object{"v": 1, "u": "test"}, Array{Object{"nested": true}}, math.NaN(), math.Inf(1), string([]byte{0xff})} {
		if _, err := PHPJSON(input, true); err == nil {
			t.Errorf("accepted ambiguous/invalid identity value %T", input)
		}
	}
	for _, input := range []any{Array{}, Array(nil), []string{}, []Object{}} {
		got, err := PHPJSON(input, true)
		if err != nil || string(got) != "[]" {
			t.Errorf("empty array encoded as %q (%v)", got, err)
		}
	}
}
